import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"EventLoop","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/event-loop.md","filePath":"zh/api/event-loop.md","lastUpdated":1786971590000}'),r={name:"zh/api/event-loop.md"};function l(c,t,i,n,h,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="eventloop" tabindex="-1">EventLoop <a class="header-anchor" href="#eventloop" aria-label="Permalink to &quot;EventLoop&quot;">​</a></h1><p>事件循环类，CV 驱动的帧调度，协程调度器，定时器队列。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>EventLoop</code> 管理应用的主循环，以目标帧率运行帧回调。支持 C++20 协程调度和定时器。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>Run(frame_callback)</code></td><td>启动事件循环，阻塞直到 Stop() 被调用</td></tr><tr><td><code>Stop()</code></td><td>停止事件循环</td></tr><tr><td><code>WakeUp()</code></td><td>唤醒等待中的事件循环</td></tr><tr><td><code>Schedule(task)</code></td><td>调度一个 <code>Task&lt;void&gt;</code> 协程</td></tr><tr><td><code>ScheduleSleep(duration, handle)</code></td><td>注册一个定时器，到期后恢复协程</td></tr><tr><td><code>SetTargetFps(fps)</code></td><td>设置目标帧率</td></tr><tr><td><code>GetTargetFps() -&gt; int</code></td><td>获取目标帧率</td></tr><tr><td><code>GetFrameCount() -&gt; uint64_t</code></td><td>获取已渲染帧数</td></tr></tbody></table><h2 id="协程支持" tabindex="-1">协程支持 <a class="header-anchor" href="#协程支持" aria-label="Permalink to &quot;协程支持&quot;">​</a></h2><ul><li><code>Yield()</code>：挂起协程，下一帧恢复</li><li><code>Sleep(duration)</code>：挂起协程，指定时长后恢复</li></ul><h2 id="线程安全" tabindex="-1">线程安全 <a class="header-anchor" href="#线程安全" aria-label="Permalink to &quot;线程安全&quot;">​</a></h2><p><code>Schedule()</code> 和 <code>ScheduleSleep()</code> 使用互斥锁保护，可从其他线程调用。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./task">Task</a></li><li><a href="./application">Application</a></li></ul>',12)])])}const _=e(r,[["render",l]]);export{u as __pageData,_ as default};
